Lemma nsafeA_munmap : forall mo a len,
  0 < len <= 2^40 -> 0 <= a -> a mod 4096 = 0 -> a + mmap_len len <= ATOP ->
  map_has (vm_maps (m_vmmaps mo)) (Z_to_bv 64 a) (Z_to_bv 64 (mmap_len len)) = true ->
  nsafeA NMAX (NMunmap a len) mo.
Proof.
