  acct_ok NMAX RNG A mo -> nsafeA NMAX n mo ->
  (forall rsp mo' evs, nstepA n mo rsp mo' evs ->
     exists z RNG' A', d rsp = Some z /\ fstepS n rsp RNG RNG' /\ alw_le A A' /\ TS NMAX RNG' A' (f z) mo' Q) ->
  TS NMAX RNG A (ebind (enode n d) f) mo Q.
Proof.
